Certainly! Here's an example of how you can create a simple Space Invaders game using Python and the curses library. This code creates a text-based version of the classic game:

```python
import time
import curses
import random

class SpaceInvadersGame:
    def __init__(self, height, width):
        self.height = height
        self.width = width
        self.stdscr = curses.initscr()
        curses.noecho()
        curses.cbreak()

    def draw(self):
        for i in range(self.height):
            for j in range(self.width):
                if (i,j) == self.ship:
                    self.stdscr.addstr("S", self.ship[0]-2, self.ship[1]-15)
                elif (i,j) in self.aliens:
                    self.stdscr.addstr("#", i+1, j+1)
                else:
                    self.stdscr.addstr(" ", i+1, j+1)
        self.stdscr.refresh()

    def move_ship(self):
        keys = self.stdscr.getch()
        if keys == curses.KEY_RIGHT:
            self.ship = (0, 39)
        elif keys == curses.KEY_LEFT:
            self.ship = (0, 1)

    def shoot(self):
        if len(self.aliens) == 0 or (self.ship[0], self.ship[1]) not in self.aliens:
            return False
        for i in range(self.height):
            for j in range(self.width):
                if (i,j) == self.ship:
                    continue
                elif (i,j) in self.aliens:
                    self.aliens.remove((i,j))
                    return True
        return False

    def move_aliens(self):
        for alien in self.aliens:
            alien[0] += 1
            if alien[0] >= self.height-1:
                alien[0] = 0

def main():
    game = SpaceInvadersGame(40, 80)
    ship = (random.randint(1, 39), random.randint(1, 79))
    aliens = [(i, j) for i in range(20) for j in range(1, 80, 4)]
    while True:
        game.draw()
        game.move_ship()
        if game.shoot():
            time.sleep(0.5)
            game.aliens = [(i, j) for i in range(20) for j in range(1, 80, 4)]
        game.move_aliens()
        if len(game.aliens) == 0:
            break

if __name__ == "__main__":
    main()
```

To run this script, you will need the `curses` library installed. You can install it using pip:

```bash
pip install curses
```

Once you have the necessary dependencies, you can run the Python script to start playing Space Invaders in your terminal!

